for req in pending_roommate_june:
    print(req['payment_request_id'], req['sender']['name'], req['amount'])

# Try to approve each with each available card
card_ids = [card['payment_card_id'] for card in venmo_cards]
for req in pending_roommate_june:
    approved = False
    for card_id in card_ids:
        try:
            result = apis.venmo.approve_payment_request(
                payment_request_id=req['payment_request_id'],
                access_token=venmo_login['access_token'],
                payment_card_id=card_id
            )
            print(f"Approved {req['payment_request_id']} with card {card_id}: {result}")
            approved = True
            break
        except Exception as e:
            # Check if error is insufficient funds, else maybe already completed
            if "Insufficient money in the payment card" in str(e):
                continue
            else:
                print(f"Error for {req['payment_request_id']} with card {card_id}: {e}")
                # If already completed, treat as approved
                if "already been completed" in str(e):
                    approved = True
                    break
    if not approved:
        print(f"Could not approve {req['payment_request_id']} with any card")

